  "Taxes owed": "ภาษีค้างจ่าย",
  "The company's own books, by double entry: every entry's debits equal its credits, and a mistake is undone by a reversing entry beside it.": "สมุดบัญชีของบริษัทเอง แบบบัญชีคู่: ทุกรายการเดบิตเท่ากับเครดิต และความผิดพลาดจะแก้ด้วยรายการกลับที่อยู่ข้างกัน",
  "The latest first.": "ล่าสุดก่อน",
  "What the company earns and spends is recorded here, by you or by the bookkeeper.": "สิ่งที่บริษัทได้รับและใช้จ่ายจะบันทึกไว้ที่นี่ โดยคุณหรือผู้ทำบัญชี",
  "e.g. Rent": "เช่น ค่าเช่า",
