  "Contacts": "ผู้ติดต่อ",
  "Everyone the company deals with: customers who wrote, and anyone you or the agents keep, with what was noted about them and the deals with them.": "ทุกคนที่บริษัทติดต่อด้วย ทั้งลูกค้าที่เคยเขียนมา และใครก็ตามที่คุณหรือเอเจนต์บันทึกไว้ พร้อมบันทึกเกี่ยวกับพวกเขาและดีลกับพวกเขา",
  "Add a person": "เพิ่มบุคคล",
  "Find by name, organisation, address or number": "ค้นหาด้วยชื่อ องค์กร ที่อยู่ หรือหมายเลข",
  "Nobody matches that.": "ไม่มีใครตรงกัน",
  "No one yet": "ยังไม่มีใคร",
  "A customer who writes on a channel is kept here, and so is anyone you add.": "ลูกค้าที่เขียนมาทางช่องทางจะถูกบันทึกไว้ที่นี่ รวมถึงทุกคนที่คุณเพิ่ม",
  "Open deals: {count}": "ดีลที่เปิดอยู่: {count}",
  "No address or number yet": "ยังไม่มีที่อยู่หรือหมายเลข",
  "Organisation": "องค์กร",
  "Phone": "โทรศัพท์",
  "Add them": "เพิ่ม",
  "Deals": "ดีล",
  "No deal with them yet.": "ยังไม่มีดีลกับคนนี้",
  "Expected {date}": "คาดว่า {date}",
  "No value given": "ไม่ได้ระบุมูลค่า",
  "Notes": "บันทึก",
  "What the next person to serve them should know": "สิ่งที่คนถัดไปที่ดูแลพวกเขาควรรู้",
  "Note it": "บันทึกไว้",
  "Nothing noted yet.": "ยังไม่มีบันทึก",
  "You, {when}": "คุณ, {when}",
  "An agent, {when}": "เอเจนต์, {when}",
  "They have not written on a channel.": "พวกเขายังไม่เคยเขียนมาทางช่องทางใด",
  "A new deal": "ดีลใหม่",
  "e.g. Coffee for 40 rooms, every month": "เช่น กาแฟสำหรับ 40 ห้อง ทุกเดือน",
  "Worth": "มูลค่า",
  "Currency": "สกุลเงิน",
  "Expected to close": "คาดว่าจะปิด",
  "Open the deal": "เปิดดีล",
  "A person was added to the customer records": "มีการเพิ่มบุคคลในข้อมูลลูกค้า",
  "A customer record was changed": "มีการแก้ไขข้อมูลลูกค้า",
  "A customer record was archived": "มีการเก็บข้อมูลลูกค้าเข้าคลัง",
  "A customer record was put back": "มีการนำข้อมูลลูกค้ากลับมา",
  "A note was added to a customer record": "มีการเพิ่มบันทึกในข้อมูลลูกค้า",
  "A deal was opened": "มีการเปิดดีล",
  "A deal was moved on": "ดีลมีความคืบหน้า",
  "Record a customer or a deal": "บันทึกลูกค้าหรือดีล",
  "For customers": "สำหรับลูกค้า",
  "Keep it from customers": "ไม่ใช่สำหรับลูกค้า",
  "Customers may be told this": "บอกลูกค้าได้",
  "A customer channel that answers on its own answers only from documents marked for customers: a menu, prices, opening hours. Leave margins, suppliers and anything internal unmarked.": "ช่องทางลูกค้าที่ตอบเองจะตอบจากเอกสารที่ทำเครื่องหมายสำหรับลูกค้าเท่านั้น เช่น เมนู ราคา เวลาเปิดทำการ อย่าทำเครื่องหมายกำไร ซัพพลายเออร์ และข้อมูลภายในใด ๆ",
  "What customers write to the company, and what it answered. Each message starts work for the role you chose; a reply waits for your yes unless its channel answers on its own.": "สิ่งที่ลูกค้าเขียนถึงบริษัท และสิ่งที่บริษัทตอบ ทุกข้อความจะเริ่มงานให้บทบาทที่คุณเลือก คำตอบจะรอการอนุมัติของคุณ เว้นแต่ช่องทางนั้นตอบเอง",
  "Let a channel answer customers on its own": "ให้ช่องทางตอบลูกค้าเอง",
  "{channel} answers on its own from documents marked for customers.": "{channel} ตอบเองจากเอกสารที่ทำเครื่องหมายสำหรับลูกค้า",
  "Every reply on {channel} waits for your yes again.": "ทุกคำตอบใน {channel} กลับมารอการอนุมัติของคุณอีกครั้ง",
  "Answers on its own": "ตอบเอง",
  "From documents marked for customers, checked before it goes. Refunds, prices of its own, complaints and the law still come to you.": "จากเอกสารที่ทำเครื่องหมายสำหรับลูกค้า และตรวจก่อนส่ง การคืนเงิน ราคาที่ตั้งเอง ข้อร้องเรียน และเรื่องกฎหมายยังคงมาถึงคุณ",
  "Sent on its own, from {documents}": "ส่งเอง จาก {documents}",
  "Went without you: the check found it grounded in documents for customers": "ส่งไปโดยไม่ผ่านคุณ: การตรวจพบว่ามีที่มาจากเอกสารสำหรับลูกค้า",
  "A reply to a customer was checked against documents for customers": "คำตอบถึงลูกค้าถูกตรวจเทียบกับเอกสารสำหรับลูกค้า",
  "A customer channel was let answer on its own": "ช่องทางลูกค้าได้รับอนุญาตให้ตอบเอง",
  "A customer channel waits for your yes again": "ช่องทางลูกค้ากลับมารอการอนุมัติของคุณ",
