  "Adds a strategist who reviews the week every Monday and proposes what to do next. Nothing it proposes happens without you.": "เพิ่มนักวางกลยุทธ์ที่ทบทวนสัปดาห์ที่ผ่านมาทุกวันจันทร์และเสนอว่าควรทำอะไรต่อ ไม่มีข้อเสนอใดเกิดขึ้นจริงโดยไม่ผ่านคุณ",
  "After the work reads something from outside the company, such as an email or a web page, a model looks at each small action it then takes and sends you the doubtful ones. It never lets through what would otherwise ask you. Each look is a model call the company pays for.": "หลังจากงานอ่านข้อมูลจากภายนอกบริษัท เช่น อีเมลหรือหน้าเว็บ โมเดลจะตรวจดูทุกการกระทำเล็กๆ ที่งานทำต่อจากนั้น และส่งรายการที่น่าสงสัยมาให้คุณ โดยไม่ปล่อยผ่านสิ่งที่ปกติต้องถามคุณอยู่แล้ว การตรวจแต่ละครั้งคือการเรียกโมเดลที่บริษัทต้องจ่าย",
  "After this, each division that uses it needs its key, named {alias}, given on Team, in the division.": "หลังจากนี้ แต่ละฝ่ายที่ใช้บริการนี้ต้องมีคีย์ชื่อ {alias} ซึ่งกำหนดได้ที่หน้าทีม ภายในฝ่ายนั้น",
