  "An API key for a service account, which an organisation admin makes; a personal token is refused.": "คีย์ API ของบัญชีบริการ (service account) ที่ผู้ดูแลองค์กรเป็นผู้สร้าง ระบบไม่รับโทเค็นส่วนตัว",
