  "As the run reported it. Every criterion has to be answered and shown before the task counts as done. Verified evidence cites a tool call of this task that the platform found succeeded; claimed evidence is the run's word, for you or a reviewer to judge.": "ตามที่รอบการทำงานรายงาน ทุกเกณฑ์ต้องได้รับคำตอบพร้อมหลักฐานก่อนงานจะนับว่าเสร็จ หลักฐานที่ยืนยันแล้วอ้างถึงการเรียกเครื่องมือของงานนี้ที่แพลตฟอร์มพบว่าสำเร็จ ส่วนหลักฐานที่อ้างเองคือคำบอกเล่าของรอบการทำงาน ให้คุณหรือผู้ตรวจทานเป็นผู้พิจารณา",
