  "Documents the company keeps. Runs are told which exist and find the passages their question points at when they search what the company knows.": "เอกสารที่บริษัทเก็บไว้ รอบการทำงานจะได้รับแจ้งว่ามีเอกสารใดบ้าง และพบส่วนข้อความที่ตรงกับคำถามเมื่อค้นหาสิ่งที่บริษัทรู้",
