  "Draft an email": "ร่างอีเมล",
  "Durable cron in the schedule's own time zone. A schedule whose last five runs said the same thing asks you whether it is still worth running.": "cron ที่ไม่หายเมื่อระบบรีสตาร์ต ตามเขตเวลาของกำหนดการเอง กำหนดการที่ห้ารอบล่าสุดให้ผลเหมือนกันจะถามคุณว่ายังควรเรียกใช้ต่อหรือไม่",
  "Each code works once. It adds a device or takes a lost one off; it does not approve.": "รหัสแต่ละชุดใช้ได้ครั้งเดียว ใช้เพิ่มอุปกรณ์หรือนำอุปกรณ์ที่หายออก แต่ใช้อนุมัติไม่ได้",
  "Each division that uses it needs its key, named {alias}: give it on Team, in the division.": "แต่ละฝ่ายที่ใช้บริการนี้ต้องมีคีย์ชื่อ {alias} กำหนดได้ที่หน้าทีม ภายในฝ่ายนั้น",
  "Each is checked against the rules a vendor file is held to before it is saved, and roles reach it only through its capability, at its tier.": "แต่ละรายการจะถูกตรวจตามกฎเดียวกับไฟล์ผู้ให้บริการก่อนบันทึก และบทบาทเข้าถึงได้ผ่านความสามารถของรายการนั้นตามระดับของมันเท่านั้น",
  "Each version is the charter as that change left it. Putting one back is a change of its own, and is recorded.": "แต่ละเวอร์ชันคือกฎบัตรหลังการเปลี่ยนแปลงครั้งนั้น การนำเวอร์ชันใดกลับมาใช้นับเป็นการเปลี่ยนแปลงอีกครั้งหนึ่ง และจะถูกบันทึกไว้",
  "Each version is the policy as that change left it. Putting one back is a change of its own, and is recorded.": "แต่ละเวอร์ชันคือนโยบายหลังการเปลี่ยนแปลงครั้งนั้น การนำเวอร์ชันใดกลับมาใช้นับเป็นการเปลี่ยนแปลงอีกครั้งหนึ่ง และจะถูกบันทึกไว้",
  "Each version is the role as it was before that change. Putting one back is a change of its own, and is recorded.": "แต่ละเวอร์ชันคือบทบาทก่อนการเปลี่ยนแปลงครั้งนั้น การนำเวอร์ชันใดกลับมาใช้นับเป็นการเปลี่ยนแปลงอีกครั้งหนึ่ง และจะถูกบันทึกไว้",
