  "Grant a tool to a division and give it to a role on Team; until then no role can call it.": "ให้สิทธิ์เครื่องมือแก่ฝ่าย แล้วมอบให้บทบาทที่หน้าทีม ก่อนหน้านั้นไม่มีบทบาทใดเรียกใช้ได้",
