  "Learned from content the company did not write, such as an email or a web page. Runs are shown it as data, never as a known fact.": "เรียนรู้จากเนื้อหาที่บริษัทไม่ได้เขียนเอง เช่น อีเมลหรือหน้าเว็บ รอบการทำงานจะเห็นสิ่งนี้เป็นเพียงข้อมูล ไม่ใช่ข้อเท็จจริงที่รู้แน่ชัด",
  "Learning from recent work failed": "การเรียนรู้จากงานล่าสุดล้มเหลว",
  "Leave empty for a division of its own. Divisions go two levels deep at most.": "เว้นว่างเพื่อให้เป็นฝ่ายหลัก ฝ่ายซ้อนกันได้ไม่เกินสองชั้น",
  "Leave empty to use Claude's own by tier: Haiku, Sonnet and Opus.": "เว้นว่างเพื่อใช้โมเดลของ Claude ตามระดับ: Haiku, Sonnet และ Opus",
