  "Left to spend": "งบคงเหลือ",
  "Let another service start work: a payment received, a form filled in, a message relayed. Each event becomes a task for the role you choose. What it says is treated as data, and anything at tier 2 or above that the work then wants still asks you.": "ให้บริการอื่นเริ่มงานได้ เช่น เมื่อได้รับชำระเงิน มีการกรอกแบบฟอร์ม หรือมีข้อความส่งต่อมา แต่ละเหตุการณ์จะกลายเป็นงานของบทบาทที่คุณเลือก เนื้อหาของเหตุการณ์ถือเป็นข้อมูล และทุกสิ่งระดับ 2 ขึ้นไปที่งานต้องการทำต่อยังต้องถามคุณ",
