  "No runtime could take it": "ไม่มีรันไทม์ใดรับงานได้",
  "No runtime runs here yet. Setting a model key in the deployment gives every role one.": "ยังไม่มีรันไทม์ทำงานที่นี่ การตั้งค่าคีย์โมเดลในระบบนี้จะทำให้ทุกบทบาทมีรันไทม์",
