  "None made yet. Without them, a lost phone needs whoever runs the server.": "ยังไม่ได้สร้าง หากไม่มีรหัสเหล่านี้ เมื่อโทรศัพท์หายต้องพึ่งผู้ดูแลเซิร์ฟเวอร์",
