  "Nothing matches: choose \"Another OpenAI-compatible API\" and type its address": "ไม่มีรายการที่ตรงกัน: เลือก “Another OpenAI-compatible API” แล้วพิมพ์ที่อยู่",
  "Nothing needs you": "ไม่มีเรื่องรอคุณ",
  "Nothing needs you right now.": "ตอนนี้ไม่มีเรื่องรอคุณ",
  "Nothing of theirs starts while it is frozen; work in progress stops at its next step. Unfreezing takes your authenticator.": "ระหว่างแช่แข็ง จะไม่มีงานใดของบริษัทนี้เริ่มขึ้น งานที่กำลังทำจะหยุดที่ขั้นตอนถัดไป การยกเลิกการแช่แข็งต้องใช้ตัวยืนยันตัวตนของคุณ",
  "Nothing of this kind.": "ไม่มีรายการประเภทนี้",
  "Nothing owed": "ไม่มีงานค้าง",
  "Nothing spent yet.": "ยังไม่มีการใช้จ่าย",
  "Nothing that does this role's work could take it. Open the role on Team and read Who does its work, put that right, then do it again.": "ไม่มีสิ่งใดที่ทำงานของบทบาทนี้รับงานนี้ได้ เปิดบทบาทนั้นในหน้าทีม อ่านส่วน “ใครทำงานนี้” แล้วแก้ให้ถูกต้อง จากนั้นกดทำอีกครั้ง",
  "Nothing that is not an incident reaches you outside them.": "นอกช่วงเวลานี้ จะมีเพียงเหตุขัดข้องเท่านั้นที่ส่งถึงคุณ",
  "Nothing was heard in that recording.": "ไม่ได้ยินเสียงใดในไฟล์บันทึกเสียงนั้น",
  "Nothing yet. What the task produces appears here when it has something.": "ยังไม่มี ผลงานของงานนี้จะปรากฏที่นี่เมื่อมี",
  "Nous Research's agent, for some thirty providers": "เอเจนต์ของ Nous Research รองรับผู้ให้บริการราวสามสิบราย",
  "Nova-3, built for speech": "Nova-3 สร้างมาเพื่อเสียงพูด",
