  "On the machine:": "บนเครื่องนั้น:",
  "On this machine": "บนเครื่องนี้",
  "On your own machine: ollama pull nomic-embed-text": "บนเครื่องของคุณเอง: ollama pull nomic-embed-text",
  "One division": "ฝ่ายเดียว",
  "One fact, stated plainly. For example: our prices include tax.": "ข้อเท็จจริงหนึ่งข้อ เขียนให้ชัดเจน เช่น ราคาของเรารวมภาษีแล้ว",
