  "One model for every tier (optional)": "โมเดลเดียวสำหรับทุกระดับ (ไม่บังคับ)",
  "One per line.": "บรรทัดละหนึ่งรายการ",
  "One per line. Every version must still say them.": "บรรทัดละหนึ่งรายการ ทุกเวอร์ชันต้องยังมีข้อความเหล่านี้",
  "One per line. Work is checked against these before it counts as finished.": "บรรทัดละหนึ่งรายการ งานจะถูกตรวจตามรายการเหล่านี้ก่อนนับว่าเสร็จ",
  "One run may spend up to {tokens} tokens, the most its role allows a run, and more for work it hands to other roles.": "หนึ่งรอบใช้ได้สูงสุด {tokens} โทเค็น ซึ่งเป็นเพดานที่บทบาทอนุญาตต่อหนึ่งรอบ และอาจใช้มากกว่านั้นสำหรับงานที่ส่งต่อให้บทบาทอื่น",
  "One run wrote more than its role allows a run, which is what a run caught in a loop looks like. Do it again as a smaller piece of work.": "รอบการทำงานหนึ่งรอบเขียนมากกว่าที่บทบาทอนุญาตต่อรอบ ซึ่งเป็นลักษณะของรอบที่ติดอยู่ในลูป กดทำอีกครั้งโดยให้เป็นงานที่เล็กลง",
  "One testable sentence per line. Every run answers each one with evidence; name what counts when a tool it needs is not connected.": "บรรทัดละหนึ่งประโยคที่ทดสอบได้ ทุกรอบการทำงานต้องตอบแต่ละข้อพร้อมหลักฐาน ระบุด้วยว่าอะไรถือว่าใช้ได้เมื่อเครื่องมือที่ต้องใช้ยังไม่ได้เชื่อมต่อ",
  "Only an incident or an approval that cannot be undone, and only these may reach you outside your hours.": "ส่งเฉพาะเหตุขัดข้องหรือการอนุมัติที่ย้อนกลับไม่ได้ และมีเพียงสองอย่างนี้ที่ส่งถึงคุณนอกช่วงเวลาของคุณได้",
  "Only for a service that signs. A reference to the deployment's secret store, never the secret itself; it is read now to check it is there.": "เฉพาะบริการที่ลงนามข้อมูล เป็นการอ้างอิงไปยังที่เก็บข้อมูลลับของระบบ ห้ามใส่ข้อมูลลับโดยตรง ระบบจะอ่านทันทีเพื่อตรวจว่ามีอยู่จริง",
  "Only logged": "บันทึกอย่างเดียว",
  "Only work its budget stopped can be continued. Do anything else again.": "ทำต่อได้เฉพาะงานที่หยุดเพราะงบประมาณเท่านั้น งานอื่นให้ทำใหม่",
