  "Open the link PALUGADA printed in its log when it started. It ends in /#/claim/ and a code, and makes whoever opens it first the owner.": "เปิดลิงก์ที่ PALUGADA พิมพ์ไว้ในล็อกตอนเริ่มทำงาน ลิงก์นี้ลงท้ายด้วย /#/claim/ ตามด้วยรหัส และจะทำให้ผู้ที่เปิดก่อนเป็นเจ้าของ",
