  "Overview has its goals and stage. Team is its divisions and roles, Memory what it has learned, Money its budgets and spend, and History every change and decision.": "ภาพรวมแสดงเป้าหมายและระยะ ทีมคือฝ่ายและบทบาท ความจำคือสิ่งที่บริษัทเรียนรู้ การเงินคืองบประมาณและการใช้จ่าย และประวัติคือทุกการเปลี่ยนแปลงและการตัดสินใจ",
