  "P3 · when there is time": "P3 · เมื่อมีเวลา",
  "PALUGADA counts in US dollars, as providers price in them. You may read every amount in your own currency, at a rate you set; nothing is charged in it.": "PALUGADA คำนวณเป็นดอลลาร์สหรัฐ เพราะผู้ให้บริการตั้งราคาเป็นดอลลาร์สหรัฐ คุณดูจำนวนเงินทุกรายการเป็นสกุลเงินของคุณเองได้ ตามอัตราแลกเปลี่ยนที่คุณตั้งเอง โดยไม่มีการเรียกเก็บเงินใดๆ ในสกุลเงินนั้น",
  "PALUGADA is connected: incidents and irreversible approvals will arrive here.": "เชื่อมต่อ PALUGADA แล้ว: เหตุขัดข้องและการอนุมัติที่ย้อนกลับไม่ได้จะมาที่นี่",
  "PALUGADA is connected: this is where it will ask you.": "เชื่อมต่อ PALUGADA แล้ว: PALUGADA จะถามคุณที่นี่",
  "PALUGADA is connected: this is where it will tell you what needs you.": "เชื่อมต่อ PALUGADA แล้ว: PALUGADA จะแจ้งเรื่องที่รอคุณที่นี่",
  "PALUGADA is starting again to use it. Refresh in a moment.": "PALUGADA กำลังเริ่มใหม่เพื่อใช้ค่านี้ รีเฟรชอีกสักครู่",
