  "What can approve a tier 3 action in your name. Revoking takes a code from a device that is staying, and ends every session the revoked one signed in.": "สิ่งที่อนุมัติการกระทำระดับ 3 ในนามของคุณได้ การเพิกถอนต้องใช้รหัสจากอุปกรณ์ที่ยังคงใช้อยู่ และจะปิดทุกเซสชันที่อุปกรณ์ที่ถูกเพิกถอนเคยลงชื่อเข้าใช้",
