  "Where it comes from": "ที่มาของค่า",
  "Where it starts": "ค่าเริ่มต้น",
  "Where roles search the web, read pages, make pictures and speak, and what finds documents by meaning: the provider, and its key.": "บริการที่บทบาทใช้ค้นหาเว็บ อ่านหน้าเว็บ สร้างภาพ และพูด รวมถึงบริการที่ค้นหาเอกสารตามความหมาย: ผู้ให้บริการและคีย์",
  "Where the company is in its life. Runs are told it, and policies can hold things back until a stage: no paid reach before launch, for one.": "บริษัทอยู่ในช่วงใดของวงจรชีวิต รอบการทำงานจะได้รับแจ้ง และนโยบายสามารถระงับบางอย่างไว้จนถึงระยะที่กำหนด เช่น ไม่ซื้อโฆษณาก่อนเปิดตัว",
