  "Widening vouches for a skill somewhere it has not been used, so it takes your authenticator.": "การขยายขอบเขตคือการรับรองทักษะในที่ที่ยังไม่เคยใช้ จึงต้องใช้ตัวยืนยันตัวตนของคุณ",
