  "Work given to the company belongs to a project. Say what each is for: every run in it is told.": "งานที่มอบให้บริษัทจะอยู่ในโปรเจกต์ ระบุว่าแต่ละโปรเจกต์มีไว้เพื่ออะไร เพราะทุกรอบการทำงานในโปรเจกต์จะได้รับแจ้ง",
  "Work handed off": "ส่งต่องานแล้ว",
