  "Work on a ticket started": "เริ่มทำงานตามทิกเก็ตแล้ว",
  "Work you give without saying whose comes here first, and so does trouble a division cannot fix. To make another role the CEO, open that role.": "งานที่คุณมอบโดยไม่ระบุผู้รับจะมาที่นี่ก่อน เช่นเดียวกับปัญหาที่ฝ่ายแก้เองไม่ได้ หากต้องการแต่งตั้งบทบาทอื่นเป็น CEO ให้เปิดบทบาทนั้น",
