  "You can follow the company's work here, and approve or deny what waits at tier 2 and below. Everything else stays the owner's.": "คุณติดตามงานของบริษัทได้ที่นี่ และอนุมัติหรือปฏิเสธสิ่งที่รออยู่ในระดับ 2 ลงมาได้ ส่วนเรื่องอื่นทั้งหมดยังเป็นหน้าที่ของเจ้าของ",
